import java.util.ArrayList;
import java.util.List;

public class Main {

    public static double sumList(List<? extends Number> list) {
        double total = 0.0;
        for (Number num : list) {
            total += num.doubleValue();
        }
        return total;
    }

    public static void main(String[] args) {
        List<Integer> intList = new ArrayList<>();
        intList.add(1);
        intList.add(2);
        intList.add(3);

        List<Double> doubleList = new ArrayList<>();
        doubleList.add(1.1);
        doubleList.add(2.2);

        System.out.println("Integer list sum: " + sumList(intList));
        System.out.println("Double list sum: " + sumList(doubleList));
    }
}
